548→    @apply focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background;
549→  }
550→
551→  /* Custom animations */
552→  @keyframes slide-up {
553→    from {
554→      transform: translateY(10px);
555→      opacity: 0;
556→    }
557→    to {
558→      transform: translateY(0);
559→      opacity: 1;
560→    }
561→  }
562→
563→  @keyframes shimmer {
564→    0% {
565→      background-position: -1000px 0;
566→    }
567→    100% {
568→      background-position: 1000px 0;
569→    }
570→  }
571→
572→  .animate-slide-up {
573→    animation: slide-up 300ms cubic-bezier(0.4, 0, 0.2, 1);
574→  }
575→
576→  .animate-shimmer {
577→    animation: shimmer 2s infinite linear;
578→    background: linear-gradient(
579→      90deg,
580→      hsl(var(--muted)) 0%,
581→      hsl(var(--accent)) 50%,
582→      hsl(var(--muted)) 100%
583→    );
584→    background-size: 1000px 100%;
585→  }
586→
587→  /* Brutalist Typography */
588→  .brutalist-heading {
589→    font-size: clamp(48px, 8vw, 120px);
590→    font-weight: 800;
591→    letter-spacing: -0.05em;
592→    line-height: 0.9;
593→    text-transform: uppercase;
594→  }
595→
596→  .brutalist-subheading {
597→    font-size: clamp(24px, 4vw, 56px);
598→    font-weight: 700;
599→    letter-spacing: -0.025em;
600→    line-height: 1.1;
601→    text-transform: uppercase;
602→  }
603→
604→  /* Brutalist Borders */
605→  .brutalist-border {
606→    border: 6px solid hsl(var(--foreground));
607→    border-radius: 0;
608→  }
609→
610→  .brutalist-border-thick {
611→    border: 8px solid hsl(var(--foreground));
612→    border-radius: 0;
613→  }
614→
615→  .brutalist-border-mega {
616→    border: 12px solid hsl(var(--foreground));
617→    border-radius: 0;
618→  }
619→
620→  /* Brutalist Shadows - Hard, not soft */
621→  .brutalist-shadow {
622→    box-shadow: 0 10px 0 0 hsl(var(--brutalist-accent));
623→  }
624→
625→  .brutalist-shadow-hover {
626→    box-shadow: 0 12px 0 0 hsl(var(--brutalist-accent));
627→  }
628→
629→  .brutalist-shadow-sm {
630→    box-shadow: 0 6px 0 0 hsl(var(--brutalist-accent));
631→  }
632→
633→  /* Glitch Animation */
634→  @keyframes glitch {
635→    0%,
636→    100% {
637→      transform: translateX(0);
638→    }
639→    20% {
640→      transform: translateX(-5px);
641→    }
642→    40% {
643→      transform: translateX(5px);
644→    }
645→    60% {
646→      transform: translateX(-3px);
647→    }
648→    80% {
649→      transform: translateX(3px);
650→    }
651→  }
652→
653→  .animate-glitch {
654→    animation: glitch 500ms ease-in-out;
655→  }
656→
657→  /* Brutalist Entrance Animation */
658→  @keyframes brutalist-entrance {
659→    from {
660→      transform: translateY(40px) scale(0.9);
661→      opacity: 0;
662→    }
663→    to {
664→      transform: translateY(0) scale(1);
665→      opacity: 1;
666→    }
667→  }
668→
669→  .animate-brutalist-entrance {
670→    animation: brutalist-entrance 600ms cubic-bezier(0.16, 1, 0.3, 1) forwards;
671→  }
672→
673→  /* Bar Growth Animation */
674→  @keyframes bar-grow {
675→    from {
676→      transform: scaleY(0);
677→      transform-origin: bottom;
678→    }
679→    to {
680→      transform: scaleY(1);
681→      transform-origin: bottom;
682→    }
683→  }
684→
685→  .animate-bar-grow {
686→    animation: bar-grow 800ms ease-out forwards;
687→  }
688→
689→  /* Stagger delays for entrance animations */
690→  .stagger-1 {
691→    animation-delay: 80ms;
692→  }
693→  .stagger-2 {
694→    animation-delay: 160ms;
695→  }
696→  .stagger-3 {
697→    animation-delay: 240ms;
698→  }
699→  .stagger-4 {
700→    animation-delay: 320ms;
701→  }
702→  .stagger-5 {
703→    animation-delay: 400ms;
704→  }
705→
706→  /* Blueprint Scanline Animation */
707→  @keyframes scanline {
708→    0% {
709→      transform: translateY(-100%);
710→    }
711→    100% {
712→      transform: translateY(100vh);
713→    }
714→  }
715→
716→  .blueprint-scanline {
717→    position: absolute;
718→    width: 100%;
719→    height: 2px;
720→    background: linear-gradient(
721→      90deg,
722→      transparent,
723→      hsl(var(--brutalist-accent) / 0.3),
724→      transparent
725→    );
726→    animation: scanline 30s linear infinite;
727→    pointer-events: none;
728→    z-index: 1;
729→  }
730→
731→  /* Slide Down Animation (for Activity Stream) */
732→  @keyframes slide-down {
733→    from {
734→      transform: translateY(-10px);
735→      opacity: 0;
736→    }
737→    to {
738→      transform: translateY(0);
739→      opacity: 1;
740→    }
741→  }
742→
743→  .animate-slide-down {
744→    animation: slide-down 300ms ease-out forwards;
745→  }
746→
747→  /* Motion Preferences - Accessibility */
748→  @media (prefers-reduced-motion: reduce) {
749→    *,
750→    *::before,
751→    *::after {
752→      animation-duration: 0.01ms;
753→      animation-iteration-count: 1;
754→      transition-duration: 0.01ms;
755→    }
756→  }
757→
758→  /* ===========================================
759→     DENSITY MODES
760→     Use data-density attribute on container
761→     =========================================== */
762→
763→  /* Compact density */
764→  [data-density="compact"] {
765→    --density-row-height: 36px;
766→    --density-cell-padding-x: 8px;
767→    --density-cell-padding-y: 6px;
768→    --density-icon-size: 16px;
769→    --density-font-size: var(--text-xs);
770→  }
771→
772→  /* Comfortable density (default) */
773→  [data-density="comfortable"] {
774→    --density-row-height: 48px;
775→    --density-cell-padding-x: 16px;
776→    --density-cell-padding-y: 12px;
777→    --density-icon-size: 20px;
778→    --density-font-size: var(--text-sm);
779→  }
780→
781→  /* Spacious density */
782→  [data-density="spacious"] {
783→    --density-row-height: 64px;
784→    --density-cell-padding-x: 24px;
785→    --density-cell-padding-y: 20px;
786→    --density-icon-size: 24px;
787→    --density-font-size: var(--text-base);
788→  }
789→
790→  /* Density utility classes */
791→  .density-row {
792→    height: var(--density-row-height);
793→    font-size: var(--density-font-size);
794→  }
795→
796→  .density-cell {
797→    padding: var(--density-cell-padding-y) var(--density-cell-padding-x);
798→    font-size: var(--density-font-size);
799→  }
800→
801→  .density-icon {
802→    width: var(--density-icon-size);
803→    height: var(--density-icon-size);
804→  }
805→
806→  /* ===========================================
807→     PROSE WIDTHS FOR READABILITY
808→     =========================================== */
809→
810→  .prose-width {
811→    max-width: var(--prose-width);
812→  }
813→
814→  .prose-width-narrow {
815→    max-width: var(--prose-width-narrow);
816→  }
817→
818→  .prose-width-wide {
819→    max-width: var(--prose-width-wide);
820→  }
821→
822→  /* ===========================================
823→     MOTION UTILITIES
824→     Using CSS custom properties
825→     =========================================== */
826→
827→  .motion-fast {
828→    transition-duration: var(--motion-fast);
829→    transition-timing-function: var(--easing-standard);
830→  }
831→
832→  .motion-base {
833→    transition-duration: var(--motion-base);
834→    transition-timing-function: var(--easing-standard);
835→  }
836→
837→  .motion-slow {
838→    transition-duration: var(--motion-slow);
839→    transition-timing-function: var(--easing-standard);
840→  }
841→
842→  .motion-linear {
843→    transition-timing-function: var(--easing-linear);
844→  }
845→
846→  .motion-spring {
847→    transition-timing-function: var(--easing-spring);
848→  }
849→}
