'use client';

import { Badge } from '@tpmjs/ui/Badge/Badge';
import { Container } from '@tpmjs/ui/Container/Container';
import { useEffect, useState } from 'react';
import { AppHeader } from '~/components/AppHeader';
import {
  FieldsetSection,
  SectionA11yChecklists,
  SectionAccessibility,
  SectionColors,
  SectionComponentAPIs,
  SectionComponents,
  SectionContent,
  SectionContentGuidelines,
  SectionDataViz,
  SectionIconSystem,
  SectionIcons,
  SectionLayout,
  SectionMotion,
  SectionPatternFeedback,
  SectionPatternForms,
  SectionPatternNavigation,
  SectionPatternSearch,
  SectionPatternTables,
  SectionPrinciples,
  SectionSpacing,
  SectionTheming,
  SectionTypography,
} from '~/components/style-guide';

interface NavSection {
  title: string;
  items: { id: string; label: string }[];
}

const navSections: NavSection[] = [
  {
    title: 'Foundations',
    items: [
      { id: 'principles', label: 'Design Principles' },
      { id: 'colors', label: 'Color System' },
      { id: 'typography', label: 'Typography' },
      { id: 'spacing', label: 'Spacing' },
      { id: 'motion', label: 'Motion' },
    ],
  },
  {
    title: 'Systems',
    items: [
      { id: 'accessibility', label: 'Accessibility' },
      { id: 'layout', label: 'Layout' },
      { id: 'content', label: 'Content' },
      { id: 'data-viz', label: 'Data Visualization' },
      { id: 'icons', label: 'Iconography' },
    ],
  },
  {
    title: 'Implementation',
    items: [
      { id: 'theming', label: 'Theming' },
      { id: 'components', label: 'Components' },
      { id: 'api', label: 'Component APIs' },
    ],
  },
  {
    title: 'Patterns',
    items: [
      { id: 'nav-patterns', label: 'Navigation' },
      { id: 'form-patterns', label: 'Forms' },
      { id: 'feedback-patterns', label: 'Feedback' },
      { id: 'table-patterns', label: 'Tables' },
      { id: 'search-patterns', label: 'Search & Filtering' },
    ],
  },
  {
    title: 'Governance',
    items: [
      { id: 'a11y-checklists', label: 'A11y Checklists' },
      { id: 'content-guidelines', label: 'Content & Writing' },
      { id: 'icon-system', label: 'Icon System' },
    ],
  },
];

export default function StyleGuidePage(): React.ReactElement {
  const [activeTab, setActiveTab] = useState('all');
  const [radioValue, setRadioValue] = useState('option1');
  const [counterValue, setCounterValue] = useState(1234);
  const [density, setDensity] = useState<'compact' | 'comfortable' | 'spacious'>('comfortable');
  const [activeSection, setActiveSection] = useState('principles');

  // Track active section on scroll
  useEffect(() => {
    const handleScroll = () => {
      const sections = navSections.flatMap((s) => s.items.map((i) => i.id));
      for (const id of sections) {
        const element = document.getElementById(id);
        if (element) {
          const rect = element.getBoundingClientRect();
          if (rect.top <= 120 && rect.bottom > 120) {
            setActiveSection(id);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (id: string) => {
    const element = document.getElementById(id);
    if (element) {
      const offset = 80;
      const elementPosition = element.getBoundingClientRect().top + window.scrollY;
      window.scrollTo({ top: elementPosition - offset, behavior: 'smooth' });
    }
  };

  return (
    <div className="min-h-screen flex flex-col bg-background">
      <AppHeader />

      <div className="flex-1 flex">
        {/* Left Sidebar Navigation */}
        <aside className="hidden lg:block w-56 flex-shrink-0">
          <nav className="sticky top-16 h-[calc(100vh-4rem)] overflow-y-auto py-10 pl-6 pr-4">
            <div className="mb-8">
              <div className="flex items-center gap-2 mb-1">
                <div className="w-1.5 h-1.5 bg-accent" />
                <span className="font-mono text-[10px] tracking-widest uppercase text-foreground-tertiary">
                  Design System
                </span>
              </div>
              <div className="flex gap-2 mt-2 ml-3.5">
                <Badge variant="default" size="sm">
                  v2.0
                </Badge>
                <Badge variant="outline" size="sm">
                  wcag aa
                </Badge>
              </div>
            </div>

            {navSections.map((section) => (
              <div key={section.title} className="mb-7">
                <h3 className="font-mono text-[10px] text-foreground-tertiary uppercase tracking-widest mb-2 ml-3">
                  {section.title}
                </h3>
                <ul className="space-y-0.5">
                  {section.items.map((item) => (
                    <li key={item.id}>
                      <button
                        onClick={() => scrollToSection(item.id)}
                        className={`block w-full text-left px-3 py-1.5 text-[13px] transition-all duration-150 border-l-2 ${
                          activeSection === item.id
                            ? 'border-l-accent text-accent font-medium bg-accent/5'
                            : 'border-l-transparent text-foreground-secondary hover:text-foreground hover:border-l-border'
                        }`}
                      >
                        {item.label}
                      </button>
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </nav>
        </aside>

        {/* Subtle sidebar separator */}
        <div className="hidden lg:block w-px bg-border/50" />

        {/* Main Content */}
        <main className="flex-1 min-w-0 py-16">
          <Container size="lg" padding="lg">
            {/* Hero Section */}
            <div className="mb-24">
              <div className="flex items-center gap-3 mb-6">
                <div className="w-2 h-2 bg-accent" />
                <span className="font-mono text-[11px] tracking-widest uppercase text-foreground-tertiary">
                  Documentation
                </span>
              </div>
              <h1 className="font-mono text-4xl md:text-5xl lg:text-[3.5rem] font-semibold mb-8 text-foreground lowercase leading-[1.1] tracking-tight">
                tpmjs design system
              </h1>
              <p className="font-sans text-lg text-foreground-secondary max-w-2xl leading-relaxed">
                The comprehensive design system for TPMJS. This guide covers design principles,
                foundations, components, and governance rules that scale across teams, AI agents, and
                external contributors.
              </p>
              <div className="flex flex-wrap gap-3 lg:hidden mt-6">
                <Badge variant="default">v2.0</Badge>
                <Badge variant="outline">wcag aa</Badge>
                <Badge variant="outline">dark mode</Badge>
              </div>
            </div>

            {/* Mobile Table of Contents */}
            <FieldsetSection title="table of contents" id="toc" className="lg:hidden">
              <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                {navSections.map((section) => (
                  <div key={section.title}>
                    <p className="font-mono text-[10px] text-foreground-tertiary uppercase tracking-widest mb-3">
                      {section.title}
                    </p>
                    <ul className="space-y-1.5">
                      {section.items.map((item) => (
                        <li key={item.id}>
                          <button
                            onClick={() => scrollToSection(item.id)}
                            className="text-sm text-foreground-secondary hover:text-accent transition-colors"
                          >
                            {item.label}
                          </button>
                        </li>
                      ))}
                    </ul>
                  </div>
                ))}
              </div>
            </FieldsetSection>

            {/* Foundation Sections */}
            <SectionPrinciples />
            <SectionColors />
            <SectionTypography />
            <SectionSpacing />
            <SectionMotion />

            {/* Systems Sections */}
            <SectionAccessibility />
            <SectionLayout density={density} onDensityChange={setDensity} />
            <SectionContent />
            <SectionDataViz counterValue={counterValue} onCounterChange={setCounterValue} />
            <SectionIcons />

            {/* Implementation Sections */}
            <SectionTheming />
            <SectionComponents
              activeTab={activeTab}
              onTabChange={setActiveTab}
              radioValue={radioValue}
              onRadioChange={setRadioValue}
            />
            <SectionComponentAPIs />

            {/* Pattern Library Sections */}
            <SectionPatternNavigation />
            <SectionPatternForms />
            <SectionPatternFeedback />
            <SectionPatternTables />
            <SectionPatternSearch />

            {/* Governance Sections */}
            <SectionA11yChecklists />
            <SectionContentGuidelines />
            <SectionIconSystem />

            {/* Footer */}
            <div className="text-center py-16 mt-24">
              <div className="w-12 h-px bg-accent mx-auto mb-6" />
              <p className="font-mono text-[11px] tracking-widest uppercase text-foreground-tertiary">
                tpmjs design system v2.0
              </p>
              <p className="font-sans text-xs text-foreground-muted mt-2">
                built with @tpmjs/ui
              </p>
            </div>
          </Container>
        </main>
      </div>
    </div>
  );
}

