'use client';

import { Icon } from '@tpmjs/ui/Icon/Icon';
import { useCallback, useState } from 'react';

/**
 * Section container with copper-numbered anchor divider.
 * Replaces the old dashed-fieldset pattern with a cleaner section break.
 */
export function FieldsetSection({
  title,
  children,
  id,
  className = '',
}: {
  title: string;
  children: React.ReactNode;
  id?: string;
  className?: string;
}): React.ReactElement {
  return (
    <section id={id} className={`mb-24 scroll-mt-24 ${className}`}>
      {/* Section divider with title */}
      <div className="relative flex items-center mb-10">
        <div className="flex-1 h-px bg-border" />
        <span className="font-mono text-[11px] tracking-widest uppercase text-foreground-tertiary px-4 select-none">
          {title}
        </span>
        <div className="flex-1 h-px bg-border" />
      </div>
      {children}
    </section>
  );
}

/**
 * Sub-section with refined heading treatment.
 * Uppercase, letterspaced, small — creates scannable rhythm.
 */
export function SubSection({
  title,
  children,
}: {
  title: string;
  children: React.ReactNode;
}): React.ReactElement {
  return (
    <div className="mb-14 last:mb-0">
      <h3 className="font-mono text-[11px] font-semibold tracking-widest uppercase text-foreground-secondary mb-6">
        {title}
      </h3>
      {children}
    </div>
  );
}

/**
 * Color swatch card — click to copy hex value.
 */
export function ColorCard({
  name,
  color,
  hex,
  desc,
  textLight = false,
}: {
  name: string;
  color: string;
  hex: string;
  desc: string;
  textLight?: boolean;
}): React.ReactElement {
  const [copied, setCopied] = useState(false);

  const handleCopy = useCallback(() => {
    navigator.clipboard.writeText(hex).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 1500);
    });
  }, [hex]);

  return (
    <button
      type="button"
      onClick={handleCopy}
      className={`${color} p-4 border border-border text-left w-full transition-all duration-150 hover:scale-[1.02] hover:shadow-sm active:scale-[0.99] cursor-pointer group relative`}
    >
      {/* Copied indicator */}
      {copied && (
        <div className="absolute top-2 right-2">
          <Icon icon="check" size="xs" className={textLight ? 'text-white' : 'text-success'} />
        </div>
      )}
      <div
        className={`font-mono text-sm font-medium ${textLight ? 'text-white' : 'text-foreground'}`}
      >
        {name}
      </div>
      <div
        className={`font-mono text-xs ${textLight ? 'text-white/80' : 'text-foreground-secondary'} group-hover:underline`}
      >
        {copied ? 'copied!' : hex}
      </div>
      <div
        className={`font-mono text-xs mt-2 ${textLight ? 'text-white/60' : 'text-foreground-tertiary'}`}
      >
        {desc}
      </div>
    </button>
  );
}

/**
 * Do/Don't example card
 */
export function DoDontCard({
  type,
  title,
  children,
}: {
  type: 'do' | 'dont';
  title: string;
  children: React.ReactNode;
}): React.ReactElement {
  const isDo = type === 'do';
  return (
    <div
      className={`border-l-4 ${isDo ? 'border-l-success' : 'border-l-error'} bg-surface p-5 transition-all duration-150 hover:-translate-y-px hover:shadow-sm`}
    >
      <div className={`flex items-center gap-2 mb-3 ${isDo ? 'text-success' : 'text-error'}`}>
        <Icon icon={isDo ? 'check' : 'x'} size="xs" />
        <span className="font-mono text-[11px] font-semibold tracking-widest uppercase">
          {isDo ? 'do' : "don't"}
        </span>
      </div>
      <p className="font-sans text-sm text-foreground-secondary mb-4">{title}</p>
      <div className="bg-surface-2 p-4">{children}</div>
    </div>
  );
}

/**
 * Principle card with icon — hover reveals copper left accent.
 */
export function PrincipleCard({
  icon,
  title,
  description,
}: {
  icon: string;
  title: string;
  description: string;
}): React.ReactElement {
  return (
    <div className="group relative border border-border bg-surface p-6 transition-all duration-150 hover:-translate-y-px hover:shadow-sm hover:border-accent/30">
      {/* Copper accent strip on hover */}
      <div className="absolute left-0 top-0 bottom-0 w-0 bg-accent transition-all duration-200 group-hover:w-[3px]" />
      <div className="flex items-center gap-3 mb-4">
        <div className="w-9 h-9 bg-accent/8 flex items-center justify-center">
          <Icon
            icon={icon as Parameters<typeof Icon>[0]['icon']}
            size="sm"
            className="text-accent"
          />
        </div>
        <h4 className="font-mono text-sm font-medium text-foreground">{title}</h4>
      </div>
      <p className="font-sans text-sm text-foreground-secondary leading-relaxed">{description}</p>
    </div>
  );
}

/**
 * Token display row — clean hairline separators, no dashes.
 */
export function TokenRow({
  name,
  value,
  preview,
}: {
  name: string;
  value: string;
  preview?: React.ReactNode;
}): React.ReactElement {
  return (
    <div className="flex items-center gap-4 py-3.5 border-b border-border/60 last:border-0">
      <code className="font-mono text-xs text-accent w-48 shrink-0">{name}</code>
      <span className="font-mono text-xs text-foreground-secondary flex-1">{value}</span>
      {preview && <div className="w-24 shrink-0">{preview}</div>}
    </div>
  );
}

/**
 * Navigation item for table of contents
 */
export function NavItem({
  href,
  children,
  indent = false,
}: {
  href: string;
  children: React.ReactNode;
  indent?: boolean;
}): React.ReactElement {
  return (
    <a
      href={href}
      className={`block font-mono text-sm text-foreground-secondary hover:text-accent transition-colors ${indent ? 'pl-4' : ''}`}
    >
      {children}
    </a>
  );
}

